    event.preventDefault();
    // Get value from both controlled and uncontrolled components
    alert(`Email: ${email}, Message: ${messageRef.current.value}`);
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Email:
        <input
          type="email"
