import React, { Component } from 'react';

class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  // Called when an error is thrown in a child component
  static getDerivedStateFromError(error) {
    // Update state to render fallback UI
    return { hasError: true };
  }

  // Called after an error is caught, useful for logging
  componentDidCatch(error, errorInfo) {
    // Log error details to an error reporting service
    console.error("Error occurred:", error);
    console.error("Error info:", errorInfo);
  }

  // Reset the error state to try re-rendering the children
  handleRetry = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render() {
    if (this.state.hasError) {
      // Render the fallback UI with a retry button
      return (
        <div>
          <h2>Something went wrong. Please try again later.</h2>
          <button onClick={this.handleRetry}>Try Again</button>
        </div>
      );
    }

    // If no error, render the children components
    return this.props.children;
  }
}

export default ErrorBoundary;
